const vehicles = [
  { id: "veh-synth-001", name: "TRUCK-SYN-01", tripId: 7 },
  { id: "veh-synth-002", name: "TRUCK-SYN-02", tripId: 11 }
];

const geofences = [
  { id: "geo-synth-01", name: "CD Monterrey (synthetic)" },
  { id: "geo-synth-02", name: "CD Aguascalientes (synthetic)" }
];

const eventTypes = ["GeofenceEntry", "GeofenceExit"];

const vehicle = vehicles[Math.floor(Math.random() * vehicles.length)];
const geofence = geofences[Math.floor(Math.random() * geofences.length)];
const eventType = eventTypes[Math.floor(Math.random() * eventTypes.length)];

const eventId = `evt-synth-${Date.now()}-${Math.floor(Math.random() * 100000)}`;
const eventTime = new Date().toISOString();

const body = {
  eventId,
  eventTime,
  orgId: "org-synth-001",
  eventType,
  data: {
    conditions: [
      {
        type: "vehicleGeofence",
        vehicle,
        geofence,
        detectionMethod: "gps"
      }
    ]
  },
  is_synthetic: true
};

return [{ json: { body, bodyString: JSON.stringify(body) } }];

const crypto = require('crypto');

const secretBase64 = $env.SAMSARA_MOCK_SHARED_SECRET;
if (!secretBase64) {
  throw new Error('SAMSARA_MOCK_SHARED_SECRET no esta definido en el entorno de n8n');
}
const secretBuffer = Buffer.from(secretBase64, 'base64');

const item = $input.first().json;
const bodyString = item.bodyString;
const timestamp = Math.floor(Date.now() / 1000).toString();

const signedPayload = `v1:${timestamp}:${bodyString}`;
const hmac = crypto.createHmac('sha256', secretBuffer);
hmac.update(signedPayload, 'utf8');
const signatureHex = hmac.digest('hex');

return [{
  json: {
    ...item,
    timestamp,
    signatureHeader: `v1=${signatureHex}`
  }
}];
